import re,glob
files=["The_Method_1_6-2.md","The_Method_1_6___The_Register-2.md","The_Method_1_6___Mathematical_Compendium-2.md","The_Method_1_6___The_Physics_Compendium-2.md","The_Method_1_6___The_Index_of_Indices-2.md","The_Method_1_6___Spectra_Compendium-2.md","THE-LOWDIN-SOLUTION-2.md","The_Three_Body_Problem_for_Unknown_Masses_Lach-2.md"]
# T followed by a locator: digits, §, appendix letter, 'audit'
